import {profile,backupKey,cloudSave} from './profile.js';
let database;
function db(){return database??=new Promise((resolve,reject)=>{const r=indexedDB.open('free-city-mind-vault',1);r.onupgradeneeded=()=>{for(const s of ['worlds','minds'])if(!r.result.objectStoreNames.contains(s))r.result.createObjectStore(s)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
export async function loadWorld(key='active'){try{const d=await db();const saved=await new Promise((resolve,reject)=>{const t=d.transaction('worlds').objectStore('worlds').get(key);t.onsuccess=()=>resolve(t.result);t.onerror=()=>reject(t.error)});if(saved)return saved}catch{}if(key!=='active')return null;try{return JSON.parse(localStorage.getItem('freecity-v1'))}catch{return null}}
export async function saveWorld(sim){const snapshot=JSON.parse(JSON.stringify(sim));let localError;try{const d=await db();await new Promise((resolve,reject)=>{const t=d.transaction(['worlds','minds'],'readwrite');t.objectStore('worlds').put(snapshot,backupKey());for(const c of [...snapshot.citizens,...snapshot.archived])t.objectStore('minds').put({name:c.name,id:c.id,savedAt:new Date().toISOString(),brain:c.brain,memories:c.memories,observations:c.observations,reflections:c.reflections,conversations:c.conversations,relationships:c.relationships,parents:c.parents,home:c.home,died:c.died??null},`${backupKey()}/citizens/${String(c.id).padStart(4,'0')}/mind`);t.oncomplete=()=>resolve();t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Save interrupted'))})}catch(e){localError=e}if(profile)await cloudSave(snapshot);else if(localError)throw localError}
export function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
